{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/lab",
  "data": [
    {
      "name": "comments",
      "type": "readonly CommentThreadData[]",
      "required": true,
      "description": "The threads: each thread’s first comment, carrying `replies` (one level), `reactions`, transient `typingUsers`, hidden per-comment `seenBy` metadata, `anchor` for inline comments, `isResolved`, `status`, `progress`, and per-comment permissions. `seenBy` remains available to comment render callbacks. Shown in time order with `events`."
    },
    {
      "name": "events",
      "type": "readonly CommentActivityEvent[]",
      "description": "Activity on the item, interleaved with the threads by `createdAt` as compact timeline rows."
    },
    {
      "name": "currentUser",
      "type": "CommentUser",
      "description": "The viewer: their own comments get Edit and Delete, and their avatar sits beside the reply composer. Authorization stays with your app."
    },
    {
      "name": "mode",
      "type": "'interactive' | 'non-editable' | 'read-only'",
      "default": "'interactive'",
      "description": "`interactive` enables every permitted action; `non-editable` keeps create, reply, and react but removes edit and delete; `read-only` removes every control that changes data."
    },
    {
      "name": "label",
      "type": "string",
      "description": "Accessible name of the Comments region. Defaults to the localized \"Comments\"."
    },
    {
      "name": "composerPosition",
      "type": "'top' | 'bottom' | 'none'",
      "default": "'bottom'",
      "description": "Where the composer for new comments renders."
    },
    {
      "name": "density",
      "type": "'compact' | 'balanced'",
      "default": "'balanced'",
      "description": "Spacing between threads and around the list."
    },
    {
      "name": "container",
      "type": "'section' | 'card'",
      "default": "'section'",
      "description": "The parent surface. `section` renders each thread as an outlined Card; `card` renders divider-bounded Sections whose dividers overlap into single lines."
    },
    {
      "name": "layout",
      "type": "'pane' | 'embedded'",
      "default": "'pane'",
      "description": "`pane` fills its container and scrolls, with the composer docked. `embedded` takes its content’s height inside a host surface: no scroll area or dock, and on a card parent no outer rules."
    },
    {
      "name": "composerPlaceholder",
      "type": "string",
      "description": "Placeholder of the new-comment composer. Defaults to the localized \"Write a comment…\", with replies saying \"Reply to <name>…\"; a custom value replaces both."
    },
    {
      "name": "selectedThreadId",
      "type": "string | null",
      "description": "The open thread, controlled, for hosts that sync threads with a document. A host-selected thread opens its body and replies and scrolls into view without moving focus or opening the reply composer."
    },
    {
      "name": "onSelectedThreadChange",
      "type": "(threadId: string | null) => void",
      "description": "Called when the viewer opens a thread or closes the open one."
    },
    {
      "name": "composerAnchor",
      "type": "CommentAnchor",
      "description": "The passage a new comment will attach to, quoted in the composer. An anchor that arrives while the panel is on screen moves focus to the composer."
    },
    {
      "name": "onComposerAnchorDismiss",
      "type": "() => void",
      "description": "Adds Remove quoted text to the composer’s quote; clear `composerAnchor` when it is called."
    },
    {
      "name": "composerControls",
      "type": "ReactNode",
      "description": "Product-owned controls in the new-comment composer’s footer, after its attach and emoji buttons."
    },
    {
      "name": "highlightColor",
      "type": "'blue' | 'cyan' | 'gray' | 'green' | 'orange' | 'pink' | 'purple' | 'red' | 'teal' | 'yellow'",
      "default": "'yellow'",
      "description": "The palette color your app highlights passages in. Quotes draw their rule in its `--color-border-<color>` token."
    },
    {
      "name": "isLoading",
      "type": "boolean",
      "default": "false",
      "description": "Shows comment-shaped placeholders and reports the region busy."
    },
    {
      "name": "loadError",
      "type": "string",
      "description": "Shows an error Banner above the threads, for comments that failed to load."
    },
    {
      "name": "onRetryLoad",
      "type": "() => void | Promise<void>",
      "description": "Adds Retry to the `loadError` Banner; a Promise keeps Retry busy until it settles."
    },
    {
      "name": "hasOlderComments",
      "type": "boolean",
      "default": "false",
      "description": "Shows Load earlier comments above the threads."
    },
    {
      "name": "isLoadingOlder",
      "type": "boolean",
      "default": "false",
      "description": "Holds Load earlier comments busy while your app fetches the page. A Promise from `onLoadOlder` does the same on its own."
    },
    {
      "name": "onLoadOlder",
      "type": "() => void | Promise<void>",
      "description": "Loads the previous page: prepend it to `comments`. A rejected Promise shows an error Banner whose Retry takes the button’s place."
    },
    {
      "name": "isSubmitting",
      "type": "boolean",
      "default": "false",
      "description": "Host-controlled pending state for the composers. Promise callbacks get a built-in pending state as well."
    },
    {
      "name": "onComposerDraftChange",
      "type": "(value: string, context: CommentComposerContext) => void",
      "description": "Reports drafts owned inside Comments: new comments, replies, and edits. It includes programmatic seeds and reports an empty value after submit, cancel, or a target switch. Route each update by `context`; debounce and expire typing in your app."
    },
    {
      "name": "composerError",
      "type": "string",
      "description": "Host-controlled error above the new-comment composer. A rejected `onSubmit` shows its own error with Retry."
    },
    {
      "name": "reactionOptions",
      "type": "readonly CommentReactionOption[]",
      "default": "DEFAULT_COMMENT_REACTIONS",
      "description": "The reactions Add reaction offers: Like, Love, Haha, Wow, Sad, and Celebrate by default, named in the viewer’s language. Give your own options a `description` to name them."
    },
    {
      "name": "onSubmit",
      "type": "(content: string, parentCommentId?: string) => void | Promise<void>",
      "description": "Posts a comment or a reply. Replies always receive the thread’s first comment as the parent. A rejected Promise restores the draft and shows an error with Retry."
    },
    {
      "name": "onSaveEdit",
      "type": "(commentId: string, content: string) => void | Promise<void>",
      "description": "Adds Edit to the viewer’s own comments and saves the new Markdown. A rejected Promise shows an error Banner with Retry."
    },
    {
      "name": "onDelete",
      "type": "(commentId: string) => void | Promise<void>",
      "description": "Adds Delete to the viewer’s own comments, confirmed in a dialog first. A rejected Promise keeps the dialog open with the error."
    },
    {
      "name": "onRetryComment",
      "type": "(commentId: string) => void | Promise<void>",
      "description": "Adds Retry to a comment whose `status` is `error`."
    },
    {
      "name": "onReact",
      "type": "(commentId: string, reactionKey: string, option?: CommentReactionOption) => void | Promise<void>",
      "description": "Toggles the viewer’s reaction by its stable key."
    },
    {
      "name": "onResolveThread",
      "type": "(commentId: string) => void | Promise<void>",
      "description": "Adds Mark as resolved to open threads. Set `isResolved` when the call succeeds, and filter resolved threads where they should not show."
    },
    {
      "name": "onReopenThread",
      "type": "(commentId: string) => void | Promise<void>",
      "description": "Adds Reopen to resolved threads. Clear `isResolved` when the call succeeds."
    },
    {
      "name": "loadVersions",
      "type": "(commentId: string) => Promise<readonly CommentVersion[]>",
      "description": "Loads a comment’s edit history, newest first. `previousVersions` works when the data is already loaded."
    },
    {
      "name": "onUploadImages",
      "type": "(files: readonly File[], context: CommentComposerContext) => CommentUploadedImage[] | Promise<CommentUploadedImage[]>",
      "description": "Uploads images attached, pasted, or dropped in a composer and appends them as Markdown images. Your endpoint authorizes the viewer and validates the files."
    },
    {
      "name": "composerTriggers",
      "type": "readonly ChatComposerTrigger[]",
      "description": "Typeahead triggers for every composer, such as an `@` people search whose tokens your Markdown plugins render."
    },
    {
      "name": "agentCommands",
      "type": "readonly CommentAgentCommand[]",
      "description": "Agents a comment can address: typing `/` lists them, and a posted comment shows the command as the agent’s chip. Your app runs the agent."
    },
    {
      "name": "markdownPlugins",
      "type": "readonly MarkdownPluginEntry[]",
      "description": "Block Markdown plugins for comment bodies, such as embeds for your own entities."
    },
    {
      "name": "markdownInlinePlugins",
      "type": "readonly MarkdownInlinePlugin[]",
      "description": "Inline Markdown plugins for comment bodies, such as the mentions your triggers insert."
    },
    {
      "name": "getReplyMention",
      "type": "(author: CommentUser) => string | undefined",
      "description": "Seeds a reply to a reply with a mention of its author in your mention format."
    },
    {
      "name": "hasEmojiPicker",
      "type": "boolean",
      "default": "true",
      "description": "Whether composers offer the emoji picker."
    },
    {
      "name": "emptyState",
      "type": "ReactNode",
      "description": "Replaces the default no-comments state."
    },
    {
      "name": "renderAnchor",
      "type": "(comment: CommentThreadData, defaultAnchor: ReactNode) => ReactNode",
      "description": "Replaces a thread’s quoted passage, for example to link it back to the document."
    },
    {
      "name": "renderBody",
      "type": "(comment: CommentData) => ReactNode",
      "description": "Replaces a comment’s Markdown body."
    },
    {
      "name": "renderVersionBody",
      "type": "(version: CommentVersion) => ReactNode",
      "description": "Replaces the body of a version in the edit history."
    },
    {
      "name": "renderEvent",
      "type": "(event: CommentActivityEvent) => ReactNode",
      "description": "Replaces an activity event’s timeline row."
    },
    {
      "name": "renderAdditionalActions",
      "type": "(comment: CommentData) => ReactNode",
      "description": "Adds product actions to a comment’s header, after the built-in ones."
    },
    {
      "name": "renderComposer",
      "type": "(props: CommentComposerRenderProps) => ReactNode",
      "description": "Replaces every composer’s input while the panel keeps its draft, pending, error, and context state. Your composer owns its own focus and keyboard handling."
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
